import React, { useState } from 'react';
import {
  Button,
  ButtonSize,
  ButtonVariant,
  HelpText,
  HelpTextSeverity,
} from '@metamask/design-system-react';
import {
  Box,
  FormTextField,
  FormTextFieldSize,
} from '../../../component-library';
import {
  BackgroundColor,
  BlockSize,
  BorderRadius,
  Display,
  FlexDirection,
  JustifyContent,
  TextVariant,
} from '../../../../helpers/constants/design-system';
import { useI18nContext } from '../../../../hooks/useI18nContext';
import { isWebUrl } from '../../../../../shared/lib/url-utils';

const AddBlockExplorerModal = ({
  onAdded,
}: {
  onAdded: (url: string) => void;
}) => {
  const t = useI18nContext();
  const [url, setUrl] = useState<string>();
  const error =
    url && url.length > 0 && !isWebUrl(url) ? t('urlErrorMsg') : undefined;

  return (
    <Box
      className="add-block-explorer-modal"
      display={Display.Flex}
      flexDirection={FlexDirection.Column}
      justifyContent={JustifyContent.spaceBetween}
      height={BlockSize.Full}
    >
      <Box paddingLeft={4} paddingRight={4}>
        <FormTextField
          size={FormTextFieldSize.Lg}
          textFieldProps={{ borderRadius: BorderRadius.LG }}
          error={Boolean(error)}
          id="additional-rpc-url"
          label={t('blockExplorerUrl')}
          inputProps={{
            'data-testid': 'explorer-url-input',
          }}
          labelProps={{
            children: undefined,
            variant: TextVariant.bodyMdMedium,
          }}
          onChange={(e) => setUrl(e.target.value)}
          autoFocus
        />
        {error && (
          <HelpText severity={HelpTextSeverity.Danger}>{error}</HelpText>
        )}
      </Box>
      <Box
        className="add-block-explorer-modal__footer"
        backgroundColor={BackgroundColor.backgroundDefault}
        padding={4}
        width={BlockSize.Full}
      >
        <Button
          isFullWidth
          isDisabled={Boolean(error)}
          size={ButtonSize.Lg}
          variant={ButtonVariant.Primary}
          data-testid="add-block-explorer-url-button"
          onClick={async () => {
            if (url) {
              onAdded(url);
            }
          }}
        >
          {t('addUrl')}
        </Button>
      </Box>
    </Box>
  );
};

export default AddBlockExplorerModal;
