import React, { useRef, useState } from 'react';
import {
  Button,
  ButtonSize,
  ButtonVariant,
  HelpText,
  HelpTextSeverity,
} from '@metamask/design-system-react';
import {
  Box,
  FormTextField,
  FormTextFieldSize,
} from '../../../component-library';
import {
  BackgroundColor,
  BlockSize,
  BorderRadius,
  Display,
  FlexDirection,
  JustifyContent,
  TextVariant,
} from '../../../../helpers/constants/design-system';
import { useI18nContext } from '../../../../hooks/useI18nContext';
import { isWebUrl } from '../../../../../shared/lib/url-utils';

const AddRpcUrlModal = ({
  onAdded,
}: {
  onAdded: (url: string, name?: string) => void;
}) => {
  const t = useI18nContext();

  const [url, setUrl] = useState<string>();
  const nameRef = useRef<HTMLInputElement>(null);
  const error = (() => {
    if (!url || isWebUrl(url)) {
      return undefined;
    }
    if (isWebUrl(`https://${url}`)) {
      return t('urlErrorMsg');
    }
    return t('invalidRPC');
  })();

  return (
    <Box
      className="add-rpc-modal"
      display={Display.Flex}
      flexDirection={FlexDirection.Column}
      justifyContent={JustifyContent.spaceBetween}
      height={BlockSize.Full}
    >
      <Box paddingTop={4} paddingLeft={4} paddingRight={4}>
        <FormTextField
          id="rpcUrl"
          size={FormTextFieldSize.Lg}
          error={Boolean(error)}
          label={t('rpcUrl')}
          placeholder={t('enterRpcUrl')}
          textFieldProps={{ borderRadius: BorderRadius.LG }}
          labelProps={{
            children: undefined,
            variant: TextVariant.bodyMdMedium,
          }}
          inputProps={{
            'data-testid': 'rpc-url-input-test',
          }}
          onChange={(e) => setUrl(e.target.value)}
          autoFocus
        />
        {error && (
          <HelpText severity={HelpTextSeverity.Danger}>{error}</HelpText>
        )}
        <FormTextField
          id="rpcName"
          size={FormTextFieldSize.Lg}
          inputProps={{
            'data-testid': 'rpc-name-input-test',
          }}
          placeholder={t('enterANameToIdentifyTheUrl')}
          paddingTop={4}
          inputRef={nameRef}
          label={t('rpcNameOptional')}
          textFieldProps={{ borderRadius: BorderRadius.LG }}
          labelProps={{
            children: undefined,
            variant: TextVariant.bodyMdMedium,
          }}
        />
      </Box>

      <Box
        className="add-rpc-modal__footer"
        backgroundColor={BackgroundColor.backgroundDefault}
        padding={4}
        width={BlockSize.Full}
      >
        <Button
          isFullWidth
          isDisabled={Boolean(error)}
          size={ButtonSize.Lg}
          variant={ButtonVariant.Primary}
          data-testid="add-rpc-url-button"
          onClick={async () => {
            if (url && !error && nameRef.current) {
              onAdded(url, nameRef.current.value || undefined);
            }
          }}
        >
          {t('addUrl')}
        </Button>
      </Box>
    </Box>
  );
};

export default AddRpcUrlModal;
